#define PI  3.14159265359
#define TAU 6.28318530718
#define DEG 0.01745329252

// TILED EXPORT. uRes is the FULL image; this is where the current tile starts within it. The
// drawing buffer only ever has to be tile-sized, so a 16K still no longer needs a 16K WebGL
// canvas — which browsers refuse well before that. Zero for an untiled render.

// camera

// march

                            // is no longer decidable in float32     // normal-probe offset, as a multiple of the hit epsilon

// IFS recursion (the fold stack is the map; this is the per-pass contraction)

// primitive

// lighting

// colour

// user image: environment map (equirectangular) and/or triplanar surface texture

// Global seed. Currently read only by the crystal cluster; the city hash is deliberately left
// unseeded so that existing presets keep rendering the same city.

// Flame IFS transforms. Uniform arrays rather than baked constants, so editing a transform in
// the panel is instant instead of a recompile. Only the COUNT is compiled in.

// Voxel field: the attractor built by chaos game and distance-transformed, sampled instead of
// estimated. Used only when the flame render mode is set to it.

// Crop box: a world-space clip applied to the finished estimate, so shadows, ambient occlusion
// and reflections all see the same cropped object rather than the uncropped one.
// Shrinks each transform's SELECTION region toward its centre. 1 = the image box as computed.
// Below 1 the regions stop overlapping, so the walk has something to discriminate on again.

// crystal cluster primitive

// city primitive

// COLOUR SOURCE and gradient shaping. What drives the palette, and how the palette is walked.

vec3 rotX(vec3 p, float a){ float c = cos(a), s = sin(a); return vec3(p.x, c*p.y - s*p.z, s*p.y + c*p.z); }
vec3 rotY(vec3 p, float a){ float c = cos(a), s = sin(a); return vec3(c*p.x + s*p.z, p.y, -s*p.x + c*p.z); }
vec3 rotZ(vec3 p, float a){ float c = cos(a), s = sin(a); return vec3(c*p.x - s*p.y, s*p.x + c*p.y, p.z); }
// Euler ZYX, degrees in. rotE3inv is its exact inverse (order reversed, angles negated).
vec3 rotE3(vec3 p, vec3 d){ return rotZ(rotY(rotX(p, d.x*DEG), d.y*DEG), d.z*DEG); }
vec3 rotE3inv(vec3 p, vec3 d){ return rotX(rotY(rotZ(p, -d.z*DEG), -d.y*DEG), -d.x*DEG); }

vec3 palette(float t){ return uPal0 + uPal1 * cos(TAU * (uPal2 * t + uPal3)); }

float sdFrame(vec3 p){
  float b = uPrimSize;
  float e = max(uPrimRound, 1e-3);
  vec3 q = abs(p) - vec3(b);
  vec3 w = abs(vec3(q.x + e, q.y + e, q.z + e)) - e;
  float a1 = length(max(vec3(q.x, w.y, w.z), 0.0)) + min(max(q.x, max(w.y, w.z)), 0.0);
  float a2 = length(max(vec3(w.x, q.y, w.z), 0.0)) + min(max(w.x, max(q.y, w.z)), 0.0);
  float a3 = length(max(vec3(w.x, w.y, q.z), 0.0)) + min(max(w.x, max(w.y, q.z)), 0.0);
  return min(a1, min(a2, a3));
}

#define FLAME_N 0
int gFlamePrev;

vec3 opOcta(vec3 p, vec4 P, inout float s, inout vec4 trap, inout float seam){
  vec3 q = abs(p);                   // explicit temps — no swizzle-write-from-swizzle-read
  if(q.x < q.y){ float t = q.x; q.x = q.y; q.y = t; }
  if(q.x < q.z){ float t = q.x; q.x = q.z; q.z = t; }
  if(q.y < q.z){ float t = q.y; q.y = q.z; q.z = t; }
  return q - vec3(P.x);              // reflections + sort + translate: isometry
}

vec3 opBoxFold(vec3 p, vec4 P, inout float s, inout vec4 trap, inout float seam){
  float L = max(P.x, 1e-3);
  return clamp(p, -L, L) * 2.0 - p;  // piecewise reflection: isometry, s unchanged
}

float prim(vec3 p){
  float d = sdFrame(p);

  return d;
}

// ── the distance estimator ──────────────────────────────────────────────────────────────
// s accumulates the local linear expansion of the whole fold stack; the estimate is the
// primitive's distance in folded space divided back out by it.
float mapTinner(vec3 p, out vec4 trap, out float safe){
  vec3 p0 = p;                        // the original sample point, for escape-time feedback
  gFlamePrev = -1;                    // no map has been undone yet, so nothing is forbidden
  float s = 1.0;
  float seam = 1e9;
  trap = vec4(1e9);

  for(int i = 0; i < 8; i++){
    p -= uO0;
    p = rotE3inv(p, uR0);
    p = opOcta(p, uP0_0, s, trap, seam);
    p = rotE3(p, uR0);
    p += uO0;
    p -= uO1;
    p = rotE3inv(p, uR1);
    p = opBoxFold(p, uP1_0, s, trap, seam);
    p = rotE3(p, uR1);
    p += uO1;
    trap = min(trap, vec4(abs(p), dot(p, p)));
    {
      vec3 d = rotE3((p - uIfsCenter) * uIfsScale, uIfsRot);
      p = d + uIfsCenter;
      s *= uIfsScale;                 // exact: rotation is free, uniform scale is k
    }

  }
  float d = prim(p) / s;
  // The seam bounds how far the marcher may ADVANCE, but it is not a surface — unless you ask
  // for it. Fold membrane mode returns the clamped value as the distance, so the marcher lands
  // on the cut plane and shades it as a visible sheet. That is the accidental look this bug
  // originally produced, kept as an opt-in effect: the mirror dimension does show you its fold
  // planes. Off by default, because a phantom surface is the wrong default.
  //
  // The bug, for the record:
  //
  // Returning min(prim/s, seam) as one number was wrong: near a tear the value goes to zero, the
  // hit test d < eps*t fires, and the marcher shades a phantom surface on the cut plane. It
  // showed up as smooth contour bands that ignored iterations, IFS scale, palette, AO and step
  // scale but tracked epsilon — the signature of a false hit, not of geometry. So the distance
  // and the safe step are now separate outputs: hit-test against the true distance, advance by
  // the clamped one.
  safe = min(d, seam);
  return d;
}

// The crop is applied HERE, once, rather than inside each estimator variant: greedy, beam and
// voxel all reach it, and so do the shadow, ambient-occlusion and reflection paths, which call
// map() rather than doing their own thing. Cropping in one estimator only would have produced an
// object whose shadow was the uncropped shape.
//
// Intersection of two distance functions is their maximum, and both sides are valid bounds, so
// the result is still a valid bound. The safe step takes the same maximum: it can only grow, and
// it stays under the true cropped distance because the inner safe step was under the inner one.
float mapT(vec3 p, out vec4 trap, out float safe){
  float d = mapTinner(p, trap, safe);

  return d;
}

float map(vec3 p){ vec4 t; float sf; return mapT(p, t, sf); }

vec3 calcNormal(vec3 p, float t){
  // The probe offset is the hit epsilon, scaled by Normal smoothing. Deliberately plain.
  //
  // Two "improvements" were tried here and both made every scene worse, so they are recorded
  // rather than repeated. Flooring at ONE PIXEL FOOTPRINT sounded right — detail below a pixel
  // cannot be displayed — but it put a visible moiré ripple across surfaces that were clean
  // before. Flooring at the estimator's cell size 1/s was worse still: 1/s is a world-space
  // length, so on any scene with a small accumulated scale it forces a probe of a large fraction
  // of a unit and destroys the shading everywhere.
  //
  // Neither had measured a benefit on the case that motivated them before being shipped.
  float e = max(uEps * t, 1e-5) * max(uNormEps, 0.25);
  vec2 k = vec2(1.0, -1.0);
  return normalize(
    vec3( k.x, k.y, k.y) * map(p + vec3( k.x, k.y, k.y) * e) +
    vec3( k.y, k.y, k.x) * map(p + vec3( k.y, k.y, k.x) * e) +
    vec3( k.y, k.x, k.y) * map(p + vec3( k.y, k.x, k.y) * e) +
    vec3( k.x, k.x, k.x) * map(p + vec3( k.x, k.x, k.x) * e));
}

// march returns hit distance, or -1.0 on miss. glowAcc is a cheap proximity accumulator:
// rays that graze the surface without hitting pick up light, which is what makes fold seams
// and fractal filigree read as emissive rather than as noise.
// The side argument is +1 outside the solid and -1 inside it. Negating the estimate lets the same routine
// walk the INTERIOR until it reaches the surface again, which is what refraction requires: a
// transmitted ray has to be tracked through the medium, not just bent at the entry face.
float march(vec3 ro, vec3 rd, float side, out float glowAcc){
  float t = uMinDist;
  float tPrev = t, dPrev = 1e30;
  glowAcc = 0.0;
  for(int i = 0; i < 160; i++){
    vec3 p = ro + rd * t;
    vec4 tr;
    float safe;
    float d = side * mapT(p, tr, safe);
    if(d < uEps * t){
      // SECANT REFINEMENT. The hit test fires as soon as the estimate drops below the epsilon,
      // so the reported distance is wherever the discrete steps happened to land — not where the
      // surface is. With a generous epsilon that quantisation is visible as concentric BANDS
      // across smooth areas, which look nothing like noise and are often mistaken for one.
      //
      // The previous sample and this one bracket the crossing, so interpolate to where the
      // estimate would reach zero. It costs no extra map() call and decouples the reported hit
      // from the step pattern, which is what removes the banding.
      float denom = dPrev - d;
      float th = (denom > 1e-20) ? (tPrev + (t - tPrev) * dPrev / denom) : t;
      return clamp(th, tPrev, t + max(d, 0.0));
    }

    // Step scale may be taken all the way to 0. The max() with uEps*t is what keeps the ray
    // moving at all: at 0 this stops being sphere tracing and becomes a FIXED-step marcher that
    // advances one hit-epsilon per iteration. That is the most robust setting against tunnelling
    // through thin sheets, and by far the slowest — it needs a large step budget to reach
    // anything, and uMaxDist is what stops it hanging.
    tPrev = t; dPrev = d;
    t += max(side * safe * uStepScale, uEps * t);
    if(t > uMaxDist) break;
  }
  return -1.0;
}

vec3 background(vec3 rd){
  vec3 L = normalize(uLightDir);
  float up = clamp(rd.y * 0.5 + 0.5, 0.0, 1.0);
  vec3 sky = mix(uBgBot, uBgTop, pow(up, 0.75));
  if(uSun > 0.001){
    float sd = max(dot(rd, L), 0.0);
    sky += vec3(1.0, 0.96, 0.88) * pow(sd, 260.0) * uSun * 3.0;   // disc
    sky += vec3(1.0, 0.90, 0.78) * pow(sd, 6.0) * uSun * 0.16;    // forward scatter
  }

  return sky;
}

// Aerial perspective: distant geometry washes toward the sky it is seen against, which is what
// gives the reference frames their depth. Plain fog to a single flat colour cannot do that.
vec3 aerial(vec3 col, vec3 rd, float t){
  float f = clamp(1.0 - exp(-uFog * t * t * 0.01), 0.0, 1.0);
  vec3 h = mix(uBgBot, uBgTop, clamp(rd.y * 0.5 + 0.5, 0.0, 1.0));
  return mix(col, h * (1.0 + uHaze * 0.4), f);
}

vec3 shadeSurface(vec3 p, vec3 n, vec3 rd, vec4 trap, float depth, out vec3 albedo){
  // WHICH trap component drives colour is a choice, and it decides the SHAPE of the banding.
  //
  // trap.w is the squared orbit radius — a radial quantity — so on a flat panel its level sets
  // are concentric rings, and a cosine palette turns them into soft contour bands that read as a
  // rendering fault. They are not: they are the colouring doing exactly what was asked.
  // The x/y/z components band along an axis instead, and their minimum bands along cell edges,
  // which sits far more naturally on the boxy structures an affine IFS produces.
  float tw;
  if(uTrapChan < 0.5)      tw = sqrt(max(trap.w, 0.0));
  else if(uTrapChan < 1.5) tw = trap.x;
  else if(uTrapChan < 2.5) tw = trap.y;
  else if(uTrapChan < 3.5) tw = trap.z;
  else                     tw = min(trap.x, min(trap.y, trap.z));
  float raw = tw;

  // COLOUR SOURCE. The orbit trap is a property of the FOLD, which is why it bands along the
  // structure — but it is not the only thing worth colouring by, and on a shape whose interest is
  // its silhouette or its depth it is the least informative choice available.
  if(uColSrc > 0.5){
    if(uColSrc < 1.5)      raw = depth * 0.25;                      // distance from the camera
    else if(uColSrc < 2.5) raw = 1.0 - clamp(dot(n, -rd), 0.0, 1.0); // facing: rim versus front
    else if(uColSrc < 3.5) raw = p.y * 0.5 + 0.5;                   // world height
    else if(uColSrc < 4.5) raw = 1.0 - 1.0;  // how enclosed it is
    else                   raw = 1.0 - abs(n.y);                    // slope: floors versus walls
  }

  float ct = raw * uTrapScale + uTrapShift;

  // GRADIENT SHAPING. Repeat walks the palette more than once across the range; mirroring makes
  // those repeats meet seamlessly instead of snapping back at every wrap, which is the difference
  // between banding that looks deliberate and banding that looks like a fault. Gamma decides
  // where the gradient spends its range, reverse flips it.
  ct *= max(uColRepeat, 0.001);
  if(uColMirror > 0.5){
    ct = abs(fract(ct * 0.5) * 2.0 - 1.0);
  } else {
    ct = fract(ct);
    if(ct < 0.0) ct += 1.0;
  }
  ct = pow(clamp(ct, 0.0, 1.0), max(uColGamma, 0.01));
  if(uColRev > 0.5) ct = 1.0 - ct;
  vec3 base = palette(ct);

  albedo = base;

  float aoV = 1.0;
  vec3  L   = normalize(uLightDir);
  float sha = 1.0;
  float dif = max(dot(n, L), 0.0);
  vec3  hv  = normalize(L - rd);
  float spe = pow(max(dot(n, hv), 0.0), 34.0) * uSpec;
  float fre = pow(1.0 - max(dot(n, -rd), 0.0), 4.0) * uRim;

  vec3 col  = base * (uAmbient * aoV + dif * sha * aoV);
  col += vec3(spe) * sha * aoV;
  col += base * fre;
  return col;
}

// One light path. Pulled out of main() so that dispersion can run it three times with a
// different IOR per channel — the physically real cause of the rainbow fringing in glass.
vec3 tracePath(vec3 ro, vec3 rd, float ior, out float glowTot){
  vec3 accum = vec3(0.0);
  vec3 atten = vec3(1.0);
  float side = 1.0;                    // +1 travelling outside the solid, -1 inside it
  glowTot = 0.0;

  for(int b = 0; b < 1; b++){
    float ga = 0.0;
    float t = march(ro, rd, side, ga);
    glowTot += ga * (b == 0 ? 1.0 : 0.55);

    if(t < 0.0){ accum += atten * background(rd); break; }

    vec3 p = ro + rd * t;
    vec3 gn = calcNormal(p, t);
    vec3 n  = gn * side;               // always faces the incoming ray
    vec4 trap;
    float safeIgn;
    mapT(p, trap, safeIgn);

    vec3 base;
    vec3 c = shadeSurface(p, n, rd, trap, t, base);
    c = aerial(c, rd, t);

    float ct = clamp(dot(n, -rd), 0.0, 1.0);
    float F0 = clamp(uReflect, 0.0, 1.0);
    float F  = (F0 + (1.0 - F0) * uFresnel * pow(1.0 - ct, 5.0)) * (1.0 - clamp(1.0 - exp(-uFog * t * t * 0.01), 0.0, 1.0));

    accum += atten * c;
    break;
  }
  return accum;
}
